#!/usr/bin/env node
// stage0-ladder-autofire.cjs (v2 — direct execution)
//
// UserPromptSubmit hook that AUTO-EXECUTES the non-Google Research Source Ladder
// when user invokes a research-trigger command. The hook itself runs the Python
// ladder runner, parses JSON output, and injects structured findings into Claude's
// context BEFORE Claude sees the prompt.
//
// Key change from v1: hook does the work, doesn't just remind. By the time Claude
// reads the user prompt, the ladder has already probed 15-30 sources and the
// drill-recommended list is in context.
//
// Triggers: /stage0, /ck:brainstorm, /ck:opportunity, /brainstorm, /venture,
//           /launch, /startup. EXCLUDED: /ck:test, /ck:validate (per user request —
//           these are hypothesis tests, not exhaustive research).
//
// Performance:
// - Cache hit (within route TTL) → ~50ms
// - Cache miss → 15-25s (parallel ladder execution)
// - Topic <10 chars → skipped (not a real research request)
//
// Ships as part of ugblackmmo-content-extraction-gap fix v2 (2026-04-11).

const fs = require('fs');
